fn read_string(self: Lexer) -> String raise String {
  let mut buf = StringBuilder::new()
  loop {
    let c = self.advance()
    if c == '"' {
      break
    } else if c == '\\' {
      let esc = self.advance()
      match esc {
        '"' => buf.write_char('"')
        '\\' => buf.write_char('\\')
        'n' => buf.write_char('\n')
        't' => buf.write_char('\t')
        _ => raise "invalid escape sequence: \\\{esc}"
      }
    } else if c == '\n' || c == EOF_CHAR {
      raise "unterminated string"
    } else {
      buf.write_char(c)
