      List::Cons(k, List::Nil) => {
        if m.contains(k) {
          raise "duplicate key: \{k}"
        }
        m[k] = val
      }
      List::Cons(k, rest) => {
        if m.contains(k) {
          // Check if existing value is a sub-object to recurse into.
          let existing = m[k]
          match existing {
            Json::Object(sub) => {
              // Use existing sub-object
              let mut sub_mut = sub
              insert_rec(&sub_mut, rest, val)?
              m[k] = Json::object(sub_mut)
            }
            _ => raise "duplicate key: \{k}"
          }
        } else {
          // Create a new nested map
          let mut sub_map: Map[String, Json] = Map::new()
          insert_rec(&sub_map, rest, val)?
          m[k] = Json::object(sub_map)
        }
      }
      List::Nil => {
        raise "empty key path"
      }
    }
  }
  insert_rec(map, keys, value)
}

