// --------------------------------------------------
fn List::push_back[T](self: List[T], value: T) -> List[T] {
  match self {
    List::Nil => List::Cons(value, List::Nil)
    List::Cons(hd, tl) => List::Cons(hd, tl.push_back(value))
  }
}

fn List::append[T](self: List[T], other: List[T]) -> List[T] {
  match self {
    List::Nil => other
    List::Cons(hd, tl) => List::Cons(hd, tl.append(other))
  }
}
