priv suberror ParseError(String)

let eof_char : Char = '\u{0000}'

/// Internal token type for the lexer.
priv enum Tok {
  Key(String)
  Eq
  Str(String)
  Int(Int)
  Bool(Bool)
  LBracket
  RBracket
  Dot
  Comma
  Newline
  Eof
}

/// Lexer state.
priv struct Lexer {
  input: String
  mut pos: Int
}

fn Lexer::Lexer(input: String) -> Lexer {
  { input, pos: 0 }
}

/// Peek at the current char without consuming.
fn peek(self: Lexer) -> Char {
  match self.input.get_char(self.pos) {
    Some(c) => c
    None => eof_char
  }
}

/// Advance one char and return it.
fn advance(self: Lexer) -> Char {
  let c = self.peek()
  self.pos += 1
  c
}

/// Skip whitespace (spaces and tabs), not newlines.
fn skip_ws(self: Lexer) -> Unit {
  while self.peek() is (' ' | '\t') {
    self.pos += 1
  }
}

/// Skip until end of line (for comments).
fn skip_comment(self: Lexer) -> Unit {
  while self.peek() != '\n' && self.peek() != eof_char {
    self.pos += 1
  }
}

/// Read a bare key.
fn read_bare_key(self: Lexer) -> String {
  let start = self.pos
  while self.peek() is ('a'..='z' | 'A'..='Z' | '0'..='9' | '_' | '-') {
    self.pos += 1
  }
  self.input[start:self.pos].to_owned()
}

/// Read a string value (after opening ").
/// Raises ParseError on invalid input.
fn read_string(self: Lexer) -> String raise ParseError {
  let mut buf = StringBuilder::new()
  loop {
    let c = self.advance()
    if c == '"' {
      break
    } else if c == '\\' {
      let esc = self.advance()
      match esc {
        '"' => buf.write_char('"')
        '\\' => buf.write_char('\\')
        'n' => buf.write_char('\n')
        't' => buf.write_char('\t')
        _ => raise ParseError("invalid escape sequence: \\\{esc}")
      }
    } else if c == '\n' || c == eof_char {
      raise ParseError("unterminated string")
    } else {
      buf.write_char(c)
    }
  }
  buf.to_string()
}

/// Read an integer.
fn read_int(self: Lexer) -> Int raise ParseError {
  let start = self.pos
  if self.peek() == '-' {
    self.pos += 1
  }
  while self.peek() is ('0'..='9') {
    self.pos += 1
  }
  let view = self.input[start:self.pos]
  @string.parse_int(view) catch {
    _ => raise ParseError("invalid integer: \{view}")
  }
}

/// Read an identifier (for booleans or bare keys).
fn read_ident(self: Lexer) -> String {
  let start = self.pos
  while self.peek() is ('a'..='z' | 'A'..='Z' | '0'..='9' | '_' | '-') {
    self.pos += 1
  }
  self.input[start:self.pos].to_owned()
}

/// Get the next token.
fn next_tok(self: Lexer) -> Tok raise ParseError {
  self.skip_ws()
  let c = self.peek()
  if c == '#' {
    self.skip_comment()
    if self.peek() == '\n' {
      self.pos += 1
      return Tok::Newline
    }
    if self.peek() == eof_char {
      return Tok::Eof
    }
    return self.next_tok()
  }
  if c == '\n' {
    self.pos += 1
    return Tok::Newline
  }
  if c == eof_char {
    return Tok::Eof
  }
  if c == '=' {
    self.pos += 1
    return Tok::Eq
  }
  if c == '[' {
    self.pos += 1
    return Tok::LBracket
  }
  if c == ']' {
    self.pos += 1
    return Tok::RBracket
  }
  if c == '.' {
    self.pos += 1
    return Tok::Dot
  }
  if c == ',' {
    self.pos += 1
    return Tok::Comma
  }
  if c == '"' {
    self.pos += 1
    let s = self.read_string()
    return Tok::Str(s)
  }
  if c is ('0'..='9' | '-') {
    return Tok::Int(self.read_int())
  }
  if c is ('a'..='z' | 'A'..='Z' | '_') {
    let ident = self.read_ident()
    if ident == "true" {
      return Tok::Bool(true)
    }
    if ident == "false" {
      return Tok::Bool(false)
    }
    return Tok::Key(ident)
  }
