}

/// A parsed TOML entry: a key path (e.g. ["owner", "name"]) and its value.
priv struct Entry {
  keys: Array[String]
  value: Json
}

/// Parser state.
priv struct Parser {
  lexer: Lexer
  mut current_tok: Tok
}

fn Parser::Parser(input: String) -> Parser {
  let lex = Lexer(input)
  let p = { lexer: lex, current_tok: Tok::Newline }
  p.advance()
  p
}

/// Advance to next token.
fn advance(self: Parser) -> Unit {
  self.current_tok = self.lexer.next_tok()
}

fn expect(self: Parser, expected: Tok) -> Unit raise ParseError {
  let got = self.current_tok
  let ok = match (got, expected) {
    (Tok::Eof, Tok::Eof) => true
    (Tok::Eq, Tok::Eq) => true
    (Tok::LBracket, Tok::LBracket) => true
    (Tok::RBracket, Tok::RBracket) => true
    (Tok::Dot, Tok::Dot) => true
    (Tok::Comma, Tok::Comma) => true
    (Tok::Newline, Tok::Newline) => true
    (Tok::Key(_), Tok::Key(_)) => true
    (Tok::Str(_), Tok::Str(_)) => true
    (Tok::Int(_), Tok::Int(_)) => true
    (Tok::Bool(_), Tok::Bool(_)) => true
    _ => false
  }
  if !ok {
    raise ParseError("expected \{token_desc(expected)}, got \{token_desc(got)}")
  }
  self.advance()
}

fn token_desc(tok: Tok) -> String {
  match tok {
    Tok::Eof => "EOF"
    Tok::Eq => "'='"
    Tok::LBracket => "'['"
    Tok::RBracket => "']'"
    Tok::Dot => "'.'"
    Tok::Comma => "','"
    Tok::Newline => "newline"
    Tok::Key(_) => "key"
    Tok::Str(_) => "string"
    Tok::Int(_) => "integer"
    Tok::Bool(_) => "boolean"
  }
}

/// Parse one or more dot-separated keys.
fn parse_keys(self: Parser) -> Array[String] raise ParseError {
  let mut keys: Array[String] = []
  loop {
    match self.current_tok {
      Tok::Key(k) => {
        keys.push(k)
        self.advance()
      }
      _ => raise ParseError("expected a key")
    }
    match self.current_tok {
      Tok::Dot => self.advance()
      _ => break
    }
  }
  keys
}

/// Parse a table header like [foo] or [foo.bar].
/// Assumes the opening '[' has been consumed.
fn parse_table_header(self: Parser) -> Array[String] raise ParseError {
  let keys = self.parse_keys()
  self.expect(Tok::RBracket)
  // Skip trailing newlines until we see a key or EOF.
  while self.current_tok is Tok::Newline {
    self.advance()
  }
  keys
}

/// Parse a value: string, integer, boolean, or array.
fn parse_value(self: Parser) -> Json raise ParseError {
  match self.current_tok {
    Tok::Str(s) => {
      self.advance()
      Json::string(s)
    }
    Tok::Int(n) => {
      self.advance()
      let text = n.to_string()
      Json::number(n.to_double(), repr=text)
    }
    Tok::Bool(b) => {
      self.advance()
      Json::boolean(b)
    }
    Tok::LBracket => {
      self.advance()
      let mut elems: Array[Json] = []
      loop {
        if self.current_tok is Tok::RBracket {
          self.advance()
          break
        }
        if elems.length() > 0 {
          self.expect(Tok::Comma)
        }
        elems.push(self.parse_value()?)
      }
      Json::array(elems)
    }
    _ => raise ParseError("expected a value, got \{token_desc(self.current_tok)}")
  }
}

/// Concatenate two arrays into a new array.
fn concat_arrays[T](a: Array[T], b: Array[T]) -> Array[T] {
  let mut result: Array[T] = []
  for elem in a {
    result.push(elem)
  }
  for elem in b {
    result.push(elem)
  }
  result
}

/// Parse a key = value line.
fn parse_keyval(self: Parser) -> Entry raise ParseError {
  let keys = self.parse_keys()
  self.expect(Tok::Eq)
  let val = self.parse_value()?
  // Consume trailing newlines
  while self.current_tok is Tok::Newline {
    self.advance()
  }
  { keys, value: val }
}

/// Parse all entries from the input.
fn parse_entries(self: Parser) -> Array[Entry] raise ParseError {
  let mut entries: Array[Entry] = []
  let mut current_prefix: Array[String] = []

  loop {
    match self.current_tok {
      Tok::Eof => break
      Tok::LBracket => {
        self.advance()
        let table_keys = self.parse_table_header()
        current_prefix = table_keys
      }
      Tok::Key(_) => {
        let entry = self.parse_keyval()
        let full_keys = concat_arrays(current_prefix, entry.keys)
        entries.push({ keys: full_keys, value: entry.value })
      }
      Tok::Newline => {
        self.advance()
      }
      _ => raise ParseError("unexpected token: \{token_desc(self.current_tok)}")
    }
  }

  entries
}

/// Convert entries into a nested Json object.
fn entries_to_json(entries: Array[Entry]) -> Json raise ParseError {
  let mut root: Map[String, Json] = Map::new()
  for entry in entries {
    insert_into(&root, entry.keys, entry.value)?
  }
  Json::object(root)
}

/// Insert a value at a dotted key path into a nested map.
fn insert_into(
  map: &Map[String, Json],
  keys: Array[String],
  value: Json
) -> Unit raise ParseError {
  fn insert_rec(
    m: &Map[String, Json],
    ks: ArrayView[String],
    val: Json
  ) -> Unit raise ParseError {
    if ks.length() == 0 {
      raise ParseError("empty key path")
    }
    let k = ks[0]
    if ks.length() == 1 {
      if m.contains(k) {
        raise ParseError("duplicate key: \{k}")
      }
      m[k] = val
    } else {
      let rest = ks[1:]
      if m.contains(k) {
        let existing = m[k]
        match existing {
          Json::Object(sub) => {
            let mut sub_mut = sub
            insert_rec(&sub_mut, rest, val)?
            m[k] = Json::object(sub_mut)
          }
          _ => raise ParseError("duplicate key: \{k}")
        }
      } else {
        let mut sub_map: Map[String, Json] = Map::new()
        insert_rec(&sub_map, rest, val)?
        m[k] = Json::object(sub_map)
      }
    }
  }
  insert_rec(map, keys, value)
}

/// Parse TOML text into a Json value.
/// On success returns Json::Object.
pub fn parse_toml(input: String) -> Json raise ParseError {
  let parser = Parser(input)
  let entries = parser.parse_entries()
  let result = entries_to_json(entries)?
  result
}
